python - <<'PY'
import doctest
import semver

result = doctest.testmod(semver, extraglobs={'semver': semver})
assert result.failed == 0, result
for version in (semver.VersionInfo(1, 2, 3), semver.VersionInfo.parse('1.2.3-rc.1+build.2')):
    parts = version.to_tuple()
    expected = dict(zip(('major', 'minor', 'patch', 'prerelease', 'build'), parts))
    assert version.to_dict() == expected
    copy = version.to_dict()
    copy['major'] = 99
    assert version.major == 1
    for index in range(-5, 5):
        assert version[index] == parts[index]
    for start in (None, -8, -2, 0, 3, 8):
        for stop in (None, -8, -2, 0, 3, 8):
            for step in (None, -2, -1, 1, 2):
                key = slice(start, stop, step)
                assert version[key] == parts[key]
    for key, error in ((5, IndexError), (-6, IndexError), ('major', TypeError), (1.0, TypeError), (slice(None, None, 0), ValueError)):
        try:
            version[key]
        except error:
            pass
        else:
            raise AssertionError('Expected %s for %r' % (error, key))
print('Doctests and accessor/indexing checks passed')
PY
